// -----------------------------------------------------------------------------
// BovisSqlDataSourceBase.cs
// -----------------------------------------------------------------------------
// This file defines the BovisSqlDataSourceBase class, which serves as a base
// implementation for SQL data sources in the Bovis framework. It provides
// functionality to load schema definitions from YAML files, retrieve child data
// names based on parent relationships, and obtain SQL queries for dependent data.
// -----------------------------------------------------------------------------

using Bovis.Interfaces;
using System;
using System.Collections.Generic;
using System.Data;
using System.Data.Common;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using static Bovis.Interfaces.IBovisDataSource;

namespace Bovis.Data
{
    /// <summary>
    /// Baseclass for backends with SQL data sources. It provides methods to load schema definitions from YAML files, retrieve child data names based on parent relationships, and obtain SQL queries for dependent data. The class maintains an internal dictionary of schema entries that represent the structure of the data source and their relationships. This allows derived classes to easily manage and query the data source based on the defined schemas.
    /// </summary>
    public class BovisSqlDataSourceBase
    {
        /// <summary>
        /// Schema entries loaded from YAML files. The key is the name of the schema entry, and the value is the schema entry itself. 
        /// </summary>
        protected Dictionary<string, SchemaEntry> Schemas = new();
        /// <summary>
        /// Load yaml schema from assets folder. 
        /// </summary>
        /// <param name="file">The name of the YAML file containing the schema definitions.</param>
        protected void LoadSchemasFromAssets(string file)
        {
            string currentAssemblyPath = System.Reflection.Assembly.GetExecutingAssembly().Location;
            var path = System.IO.Path.Combine(System.IO.Path.GetDirectoryName(currentAssemblyPath)!, "assets", file);
            // deserialize from yaml
            var deserializer = new YamlDotNet.Serialization.DeserializerBuilder().Build();
            var entries = deserializer.Deserialize<Dictionary<string, SchemaEntry>>(System.IO.File.ReadAllText(path));
            // add to _schemas  
            foreach (var entry in entries)
            {                
                entry.Value.Name=entry.Key;
                Schemas[entry.Key] = entry.Value;
            }
        }
        /// <summary>
        /// Get a Schema entries that are children of the given parent. If the parent is null, it returns all schema entries that have no parent (i.e., top-level entries). This method allows you to retrieve the schema entries that are directly related to a specific parent entry, which can be useful for understanding the structure of the data and how different tables are connected based on their parent-child relationships defined in the schemas.
        /// </summary>
        /// <param name="parent">The name of the parent schema entry. If null, top-level entries are returned.</param>
        /// <returns>An enumerable of schema entries that are children of the specified parent. </returns>
        public IEnumerable<SchemaEntry> GetChildDataNames(string? parent = null)
        {
            if (parent == null) parent = String.Empty;
            foreach (var s in Schemas)
            {
                if (s.Value.Parent == parent)
                {
                    yield return s.Value;
                }
            }
        }
        /// <summary>
        /// return the sql query to get dependend data for the given table name. This can be either a custom query defined in the data source or a predefined query for known tables. If the table name starts with "select ", it is treated as a raw SQL query and returned directly.
        /// </summary>
        /// <param name="parent">The name of the parent schema entry.</param>
        /// <param name="tableName">The name of the dependend    data name for which to retrieve the dependent data query.</param>
        /// <returns>
        /// The SQL query string for the dependent data, or <c>null</c> if no query is found.
        /// </returns>
        public string? GetDependendDataQuery(string parent, string tableName)
        {
            if (tableName.StartsWith("select ", StringComparison.OrdinalIgnoreCase))
            {
                return tableName;
            }
            foreach (var q in GetChildDataNames(parent))
            {
                if (tableName == q.Name)
                {
                    return q.Query;
                }
            }
            return null;
        }

    }
}
